const $=id=>document.getElementById(id),names={economy:'Économie',wellbeing:'Bien-être',culture:'Culture',infrastructure:'Infrastructures',environment:'Environnement'},phase={weeks:'Gains hebdomadaires',vote:'Vote interne',funding:'Financement',finished:'Pilote terminé'};let model,busy=false;
const node=(tag,text,className)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(className)e.className=className;return e;};
function svg(tag,attrs={},text){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,String(v));if(text!==undefined)e.textContent=text;return e;}
function scene(city){const root=$('city-scene');root.replaceChildren();root.append(svg('path',{d:'M0 320 Q210 210 800 280 L800 380 L0 380Z',fill:'#cadbb4'}),svg('path',{d:'M40 295 Q320 320 760 295',fill:'none',stroke:'#cfbc91','stroke-width':36}));
 for(let i=0;i<6;i++){const x=45+i*140;root.append(svg('circle',{cx:x,cy:160+(i%2)*40,r:26,fill:'#86a77a'}),svg('path',{d:`M${x} 178V232`,stroke:'#7d7959','stroke-width':7}));}
 city.buildings.forEach((b,i)=>{const x=140+(i%3)*240,y=135+Math.floor(i/3)*140,g=svg('g',{transform:`translate(${x} ${y})`,class:b.condition==='damaged'?'damaged':''});g.append(svg('rect',{x:-58,y:0,width:116,height:100,rx:5,fill:b.id.includes('garden')?'#bed09a':'#e6d2a5',stroke:'#847e65','stroke-width':2}),svg('path',{d:'M-70 0 L0-48 L70 0Z',fill:b.condition==='damaged'?'#98664c':'#9e5c4a'}),svg('rect',{x:-12,y:58,width:24,height:42,fill:'#716e54'}),svg('rect',{x:-39,y:25,width:18,height:22,fill:'#b2d6d2'}),svg('rect',{x:21,y:25,width:18,height:22,fill:'#b2d6d2'}),svg('text',{x:0,y:125,'text-anchor':'middle','font-size':16,fill:'#34473b'},b.name+(b.condition==='damaged'?' · endommagé':'')));root.append(g);});$('empty-city').hidden=city.buildings.length>0;$('building-list').replaceChildren(...city.buildings.map(b=>node('li',b.name+(b.condition==='damaged'?' · endommagé':''))));root.setAttribute('aria-label','Bâtiments : '+(city.buildings.map(b=>b.name+(b.condition==='damaged'?' endommagé':'')).join(', ')||'aucun pour le moment'));}
function render(m){model=m;const operator=m.role==='operator';$('city-name').textContent=m.city.name;$('calendar').textContent=`Semaine ${m.currentWeek} / 16 · ${phase[m.stage]}`;$('development').textContent=m.city.development+' / 100';
 const role=$('role');role.replaceChildren(...m.roles.map(r=>{const e=node('option',r.label);e.value=r.id;return e;}));role.value=m.role;role.disabled=busy;document.querySelector('#funding-form button').disabled=busy;$('operator-tools').hidden=!operator;
 $('advance').disabled=busy||m.stage!=='weeks';$('close-vote').disabled=busy||m.stage!=='vote';$('close-funding').disabled=busy||m.stage!=='funding';$('automatic').disabled=busy||m.completedWeeks!==0||m.stage!=='weeks';$('reset').disabled=busy;scene(m.city);
 $('gauges').replaceChildren(...Object.entries(m.city.gauges).map(([k,v])=>{const box=node('div',undefined,'gauge'),label=node('label',names[k]),bar=node('progress');bar.max=100;bar.value=v;bar.setAttribute('aria-label',names[k]);box.append(label,bar,node('strong',v+' / 100'));return box;}));
 $('crises').replaceChildren(...m.city.crises.map(c=>node('p',`${c.name} : ${c.protected?'dégâts atténués par '+c.protectors.map(id=>m.city.buildings.find(b=>b.id===id)?.name??id).join(', '):'sans bâtiment protecteur'}. ${Object.entries(c.effects).map(([k,v])=>`${names[k]} ${v}`).join(' · ')}`, 'crisis')));
 $('family-panel').hidden=!m.myFamily;if(m.myFamily){$('family-name').textContent=m.myFamily.name;$('purse').textContent=m.myFamily.ecus;$('ambition').textContent='Favoriser '+names[m.city.myAmbition.gauge]+'.';$('milestones').textContent=[50,80].map(n=>n+' % : '+(m.city.myAmbition.milestones.some(x=>x.threshold===n)?'atteint':'à atteindre')).join(' · ');$('income').replaceChildren(...m.myFamily.credits.slice(-4).map(c=>node('li','+'+c.ecus+' écus · '+c.weekId)));}
 $('council-panel').hidden=!m.council;if(m.council){const c=m.council;$('council-number').textContent='CONSEIL '+c.ordinal+' / 4';$('dilemma').textContent=c.definition.title;$('council-state').textContent=c.phase==='resolved'?'Décision archivée':c.phase==='voting'?'Vote interne · tour '+c.round:'Vote acquis, financement en cours';
 $('projects').replaceChildren(...c.definition.projects.map(p=>{const card=node('article',undefined,'project');card.append(node('h3',p.name),node('strong',p.cost+' écus'),node('p',Object.entries(p.effects).map(([k,v])=>names[k]+' '+(v>0?'+':'')+v).join(' · ')));if(p.protection)card.append(node('p','Protection : '+({fire:'incendie',epidemic:'épidémie',barbarians:'attaque',drought:'sécheresse',earthquake:'séisme'}[p.protection])));return card;}));
 const ballot=$('ballot');ballot.replaceChildren();if(c.myFamily?.canVote){const opts=c.definition.mode==='choice'?c.definition.projects.map(p=>[p.id,p.name]):[['yes','Oui'],['no','Non']];for(const [choice,label]of [...opts,['abstain','M’abstenir']]){const b=node('button',label);b.disabled=busy;b.addEventListener('click',()=>action({type:'vote',round:c.round,choice}));ballot.append(b);}}
 $('vote-note').textContent=operator?'Les bulletins individuels et ambitions sont masqués pour l’opérateur.':c.myFamily?.suspended?'Notre famille est suspendue pour ce Conseil uniquement.':c.myFamily?.ballot?'Votre bulletin est enregistré.':'Chaque membre possède un bulletin ; le résultat interne donne une seule voix familiale.';
 $('funding-form').hidden=!(c.phase==='funding'&&m.myFamily?.canFund);if(c.myFamily){$('pledge').value=c.myFamily.pledge.amount;$('pledge').max=Math.min(m.myFamily.ecus,c.funding.remaining+c.myFamily.pledge.amount);}
 $('funding-summary').textContent=c.funding.cost!==null?`${c.funding.pledged} / ${c.funding.cost} écus promis · ${c.funding.remaining} restants${c.resolution?' · clôturé':''}.`:'';
 $('vote-results').replaceChildren(...c.rounds.map(r=>node('p','Tour '+r.round+' : '+Object.entries(r.tally).map(([k,v])=>(c.definition.projects.find(p=>p.id===k)?.name??({yes:'Oui',no:'Non'}[k])??k)+' '+v+' voix familiale'+(v>1?'s':'')).join(' · '))));
 $('resolution').textContent=c.resolution?`${c.resolution.status==='built'?'Projet réalisé':'Projet non réalisé'} · ${c.resolution.narrative} Dépense totale : ${c.resolution.cost} écus.`:'';
 }
 $('history').replaceChildren(...m.city.resolutions.map(r=>node('li',`Conseil ${r.ordinal} — ${r.status==='built'?'projet financé':'échec'} · ${r.cost} écus · ${r.narrative}`)));
}
async function request(path,data){if(busy)return;busy=true;document.querySelectorAll('button,select').forEach(e=>e.disabled=true);$('status').textContent='';try{const response=await fetch(path,data?{method:'POST',headers:{'Content-Type':'application/json','X-Prototype-CSRF':model.csrf},body:JSON.stringify(data)}:{});if(!response.ok){const error=await response.json();const fresh=await fetch('/api/state');if(fresh.ok)render(await fresh.json());throw Error(error.error);}render(await response.json());}catch(e){$('status').textContent=e.message;}finally{busy=false;if(model)render(model);}}
const action=data=>request('/api/action',{...data,revision:model.revision});$('role').addEventListener('change',()=>request('/api/role',{role:$('role').value}));for(const [id,type]of [['advance','advance-week'],['close-vote','close-vote'],['close-funding','close-funding'],['automatic','automatic'],['reset','reset']])$(id).addEventListener('click',()=>action({type}));$('funding-form').addEventListener('submit',e=>{e.preventDefault();action({type:'pledge',amount:Number($('pledge').value),pledgeRevision:model.council.myFamily.pledge.revision,mutationId:crypto.randomUUID()});});void request('/api/state');
